#!/usr/bin/env node
// Generates the shared contract into both apps, so neither one hand-writes its models,
// function names, building names, colors or text.
//
//   node scripts/generate-clients.mjs           write the files
//   node scripts/generate-clients.mjs --check   fail if any generated file is out of date
//
// Sources (in this repo):
//   types.ts, shared/callables.ts   request/response types       (TypeScript)
//   shared/callables.json           function names and region
//   shared/theme.json               colors, radii, spacing, sizes
//   shared/copy.json                player-facing text
//   geofence/buildings.geojson      building names
//
// Outputs (committed inside each submodule, so the apps build when cloned on their own):
//   ios/Gotcha/Generated/{Contract,Callables,Theme,Copy,Buildings}.swift
//   android/src/generated/{types,callables,theme,copy,buildings}.ts
//
// Swift models: TypeScript -> JSON Schema (ts-json-schema-generator) -> Swift (quicktype).

import { existsSync, mkdirSync, readFileSync, writeFileSync } from "node:fs";
import { dirname, join, relative } from "node:path";
import { fileURLToPath } from "node:url";
import { createGenerator } from "ts-json-schema-generator";
import { FetchingJSONSchemaStore, InputData, JSONSchemaInput, quicktype } from "quicktype-core";

const root = join(dirname(fileURLToPath(import.meta.url)), "..");
const check = process.argv.includes("--check");

const iosDir = join(root, "ios", "Gotcha", "Generated");
const androidDir = join(root, "android", "src", "generated");

const readJson = (path) => JSON.parse(readFileSync(join(root, path), "utf8"));
const callables = readJson("shared/callables.json");
const theme = readJson("shared/theme.json");
const copy = readJson("shared/copy.json");

// Types the apps decode or send. Nested types (Target, AdminIndexRow, ...) come along with them.
const TOP_LEVEL_TYPES = [
  "ClientProfile",
  "GameSettings",
  "GetLeaderboardResponse",
  "ClientLastWordsResponse",
  "ClientTaggedOutResponse",
  "GetProfileRequest",
  "SetLastWordsRequest",
  "StatusResponse",
];

// JSON Schema only knows "number". These are always whole numbers, so Swift gets Int
const INTEGER_FIELDS = new Set(["tags", "status", "checkInDeadline"]);

const swiftHeader = (sources) => `// GENERATED by scripts/generate-clients.mjs from ${sources}. Do not edit.
// Change the source in the Gotcha2026 repo and run \`npm run gen:clients\` there.
`;
const tsHeader = (sources) => `// GENERATED by scripts/generate-clients.mjs from ${sources}. Do not edit.
// Change the source in the Gotcha2026 repo and run \`npm run gen:clients\` there.
`;

// ---------- building names (same filter as scripts/generate-buildings.mjs) ----------

function buildingNames() {
  const geojson = readJson("geofence/buildings.geojson");
  return geojson.features
    .filter((f) =>
      typeof f?.properties?.name === "string" && f.properties.name.trim() !== "" &&
      (f.geometry?.type === "Polygon" || f.geometry?.type === "MultiPolygon"))
    .map((f) => f.properties.name.trim());
}

// ---------- Swift models ----------

function contractSchema() {
  const schema = createGenerator({
    path: join(root, "shared", "callables.ts"),
    tsconfig: undefined,
    type: "*",
    expose: "export",
    skipTypeCheck: true,
    topRef: true,
  }).createSchema("*");

  // whole-number fields
  const visit = (node) => {
    if (!node || typeof node !== "object") return;
    if (node.properties) {
      for (const [key, value] of Object.entries(node.properties)) {
        if (INTEGER_FIELDS.has(key) && value.type === "number") value.type = "integer";
        visit(value);
      }
    }
    for (const value of Object.values(node)) if (typeof value === "object") visit(value);
  };
  visit(schema.definitions);

  // quicktype wants one top-level type, so wrap them all in one and drop the wrapper afterwards
  schema.title = "ContractRoot";
  schema.type = "object";
  schema.properties = Object.fromEntries(TOP_LEVEL_TYPES.map((t) => [t, { $ref: `#/definitions/${t}` }]));
  schema.required = TOP_LEVEL_TYPES;
  schema.additionalProperties = false;
  return schema;
}

async function swiftModels() {
  const schemaInput = new JSONSchemaInput(new FetchingJSONSchemaStore());
  await schemaInput.addSource({ name: "ContractRoot", schema: JSON.stringify(contractSchema()) });
  const inputData = new InputData();
  inputData.addInput(schemaInput);

  const { lines } = await quicktype({
    inputData,
    lang: "swift",
    leadingComments: [],
    rendererOptions: {
      "struct-or-class": "struct",
      initializers: "false",
      "coding-keys": "true",
      "access-level": "internal",
      protocol: "equatable",
      sendable: "true",
    },
  });

  let swift = lines.join("\n");
  // drop the wrapper struct
  swift = swift.replace(/\/\/ MARK: - ContractRoot\n[\s\S]*?\n}\n\n/, "");
  // `class` is a keyword, so quicktype names those properties e.g. `profileClass`. Use `className`
  const classProperties = new Set([...swift.matchAll(/case (\w+) = "class"/g)].map((m) => m[1]));
  for (const name of classProperties) {
    swift = swift.replace(new RegExp(`\\b${name}\\b`, "g"), "className");
  }
  // the project defaults to MainActor isolation. Models are plain data, decoded off the main actor
  swift = swift.replace(/^(struct|enum) /gm, "nonisolated $1 ");
  return `${swiftHeader("types.ts and shared/callables.ts")}\n${swift.trim()}\n`;
}

// ---------- Swift: callables, theme, copy, buildings ----------

function swiftCallables() {
  const entries = Object.entries(callables.callables).map(([name, spec]) => {
    const request = spec.request === "EmptyRequest" ? "EmptyRequest" : spec.request;
    const response = spec.nullable ? `${spec.response}?` : spec.response;
    return `    static let ${name} = Callable<${request}, ${response}>(name: ${JSON.stringify(name)})`;
  });
  return `${swiftHeader("shared/callables.json")}
import Foundation

/// A callable Cloud Function, with the types it takes and returns.
nonisolated struct Callable<Request: Encodable & Sendable, Response: Decodable & Sendable>: Sendable {
    let name: String
}

/// Sent to callables that take no arguments (they expect \`{}\`).
nonisolated struct EmptyRequest: Codable, Sendable, Equatable {}

nonisolated enum Callables {
    static let region = ${JSON.stringify(callables.region)}

${entries.join("\n")}
}
`;
}

function swiftHexColor(hex) {
  const value = hex.replace("#", "");
  const rgb = value.slice(0, 6);
  const alpha = value.length === 8 ? parseInt(value.slice(6), 16) / 255 : 1;
  return alpha === 1 ? `Color(hex: 0x${rgb})` : `Color(hex: 0x${rgb}, opacity: ${alpha.toFixed(3)})`;
}

function swiftNumberEnum(name, values) {
  const lines = Object.entries(values).map(([key, value]) =>
    `        static let ${key}: CGFloat = ${value}`);
  return `    enum ${name} {\n${lines.join("\n")}\n    }`;
}

function swiftTheme() {
  const colors = Object.entries(theme.colors).map(([key, hex]) =>
    `        static let ${key} = ${swiftHexColor(hex)}`);
  const animation = Object.entries(theme.animation).map(([key, value]) =>
    `        static let ${key}: Double = ${value}`);
  return `${swiftHeader("shared/theme.json")}
import SwiftUI

nonisolated enum Theme {
    enum Colors {
${colors.join("\n")}
    }

${swiftNumberEnum("Radius", theme.radius)}

${swiftNumberEnum("Spacing", theme.spacing)}

${swiftNumberEnum("FontSize", theme.fontSize)}

    enum Animation {
${animation.join("\n")}
    }
}

extension Color {
    /// e.g. Color(hex: 0x0f172a)
    nonisolated init(hex: UInt32, opacity: Double = 1) {
        self.init(
            .sRGB,
            red: Double((hex >> 16) & 0xff) / 255,
            green: Double((hex >> 8) & 0xff) / 255,
            blue: Double(hex & 0xff) / 255,
            opacity: opacity
        )
    }
}
`;
}

const capitalize = (s) => s[0].toUpperCase() + s.slice(1);

function swiftCopyValue(value) {
  if (typeof value === "string") return JSON.stringify(value);
  if (typeof value === "number") return String(value);
  if (Array.isArray(value)) return `[${value.map(swiftCopyValue).join(", ")}]`;
  throw new Error(`Unsupported copy value: ${JSON.stringify(value)}`);
}

function swiftCopyEntries(object, indent) {
  const pad = " ".repeat(indent);
  return Object.entries(object)
    .filter(([key]) => !key.startsWith("$"))
    .map(([key, value]) => {
      if (value && typeof value === "object" && !Array.isArray(value)) {
        return `${pad}enum ${capitalize(key)} {\n${swiftCopyEntries(value, indent + 4)}\n${pad}}`;
      }
      return `${pad}static let ${key} = ${swiftCopyValue(value)}`;
    })
    .join("\n");
}

function swiftCopy() {
  return `${swiftHeader("shared/copy.json")}
import Foundation

nonisolated enum Copy {
${swiftCopyEntries(copy, 4)}

    /// Fills in {name} placeholders, e.g. Copy.fill(Copy.Leaderboard.startsIn, ["time": "1d 2h"])
    static func fill(_ text: String, _ values: [String: String]) -> String {
        values.reduce(text) { result, pair in
            result.replacingOccurrences(of: "{\\(pair.key)}", with: pair.value)
        }
    }
}
`;
}

function swiftBuildings(names) {
  return `${swiftHeader("geofence/buildings.geojson")}
import Foundation

nonisolated enum Buildings {
    static let names: [String] = [${names.map((n) => JSON.stringify(n)).join(", ")}]
}
`;
}

// ---------- TypeScript for the Android (Expo) app ----------

function tsFromJson(name, value, source) {
  const { $comment, ...rest } = value;
  return `${tsHeader(source)}
export const ${name} = ${JSON.stringify(rest, null, 2)} as const;
`;
}

function tsCallables() {
  const source = readFileSync(join(root, "shared", "callables.ts"), "utf8")
    .replace('from "../types"', 'from "./types"');
  const names = Object.keys(callables.callables);
  return `${tsHeader("shared/callables.ts and shared/callables.json")}
${source.trim()}

export const REGION = ${JSON.stringify(callables.region)};
export const CALLABLE_NAMES = ${JSON.stringify(names)} as const satisfies readonly CallableName[];
`;
}

function tsTypes() {
  const source = readFileSync(join(root, "types.ts"), "utf8");
  return `${tsHeader("types.ts")}
${source.trim()}
`;
}

function tsBuildings(names) {
  return `${tsHeader("geofence/buildings.geojson")}
export const BUILDING_NAMES: readonly string[] = ${JSON.stringify(names)};
`;
}

// ---------- write or check ----------

const names = buildingNames();
const outputs = [
  [join(iosDir, "Contract.swift"), await swiftModels()],
  [join(iosDir, "Callables.swift"), swiftCallables()],
  [join(iosDir, "Theme.swift"), swiftTheme()],
  [join(iosDir, "Copy.swift"), swiftCopy()],
  [join(iosDir, "Buildings.swift"), swiftBuildings(names)],
  [join(androidDir, "types.ts"), tsTypes()],
  [join(androidDir, "callables.ts"), tsCallables()],
  [join(androidDir, "theme.ts"), tsFromJson("theme", theme, "shared/theme.json")],
  [join(androidDir, "copy.ts"), tsFromJson("copy", copy, "shared/copy.json")],
  [join(androidDir, "buildings.ts"), tsBuildings(names)],
];

let stale = 0;
for (const [path, content] of outputs) {
  // a submodule that isn't checked out can't be generated into
  if (!existsSync(dirname(dirname(path))) && !existsSync(dirname(path))) {
    console.warn(`skipped ${relative(root, path)} (is the submodule checked out?)`);
    continue;
  }
  const current = existsSync(path) ? readFileSync(path, "utf8") : null;
  if (current === content) continue;
  if (check) {
    console.error(`out of date: ${relative(root, path)}`);
    stale++;
  } else {
    mkdirSync(dirname(path), { recursive: true });
    writeFileSync(path, content);
    console.log(`wrote ${relative(root, path)}`);
  }
}

if (check && stale > 0) {
  console.error(`\n${stale} generated file(s) are out of date. Run \`npm run gen:clients\`.`);
  process.exit(1);
}
if (check) console.log("Generated client files are up to date.");
